CREATE TABLE service_cases(student_id TEXT PRIMARY KEY REFERENCES students(id),org_id TEXT NOT NULL REFERENCES organizations(id),started_at INTEGER NOT NULL,target_at INTEGER NOT NULL,promised_at INTEGER NOT NULL,onboarding_revision INTEGER NOT NULL,reviewed_revision INTEGER,responsible_id TEXT REFERENCES users(id),status TEXT NOT NULL CHECK(status IN ('waiting','in_progress','needs_info','delivered')),note TEXT NOT NULL DEFAULT '',revision INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL,delivered_at INTEGER);
CREATE INDEX service_cases_due ON service_cases(org_id,status,target_at);
